CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, handle TEXT NOT NULL UNIQUE COLLATE NOCASE, salt TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS characters (id TEXT PRIMARY KEY, name TEXT NOT NULL, universe TEXT NOT NULL, portrait_url TEXT NOT NULL DEFAULT '', strength INTEGER NOT NULL, dexterity INTEGER NOT NULL, battle_iq INTEGER NOT NULL, endurance INTEGER NOT NULL, hacks INTEGER NOT NULL, iq INTEGER NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS daily_drafts (user_id TEXT NOT NULL REFERENCES users(id), day TEXT NOT NULL, current_character_id TEXT REFERENCES characters(id), submitted_at TEXT, created_at TEXT NOT NULL, PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS daily_picks (user_id TEXT NOT NULL, day TEXT NOT NULL, stat TEXT NOT NULL CHECK(stat IN ('strength','dexterity','battle_iq','endurance','hacks','iq')), character_id TEXT NOT NULL REFERENCES characters(id), PRIMARY KEY(user_id,day,stat), UNIQUE(user_id,day,character_id));
CREATE TABLE IF NOT EXISTS stat_matchups (id TEXT PRIMARY KEY, day TEXT NOT NULL, p1 TEXT NOT NULL, p2 TEXT NOT NULL, stat TEXT NOT NULL, p1_character TEXT NOT NULL, p2_character TEXT NOT NULL, p1_value INTEGER NOT NULL, p2_value INTEGER NOT NULL, winner_id TEXT, settled_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_matchup_day ON stat_matchups(day);
CREATE INDEX IF NOT EXISTS idx_matchup_winner ON stat_matchups(winner_id,day);
CREATE TABLE IF NOT EXISTS settlements (day TEXT PRIMARY KEY, settled_at TEXT NOT NULL, player_count INTEGER NOT NULL, matchup_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS auth_attempts (ip TEXT NOT NULL, operation TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_auth_attempts ON auth_attempts(ip,operation,at);
